// Navigation commune à toutes les pages.
// Le menu mobile reste ici pour ne pas dupliquer la logique.

import React,{useState} from 'react';
import {NavLink,Link} from 'react-router-dom';
import {AnimatePresence,motion} from 'framer-motion';
import Icon from './Icon';

export function Logo(){return <Link className="brand" to="/" aria-label="Beyond31 — accueil"><img src="/images/beyond31_logo.png" alt=""/><span>Beyond31</span></Link>}
const nav=[['/','home','Accueil'],['/projets','work','Projets'],['/expertise','expertise','Compétences'],['/studio','vision','Vision']];

export default function Layout({children}){
 const [open,setOpen]=useState(false);
 return <div className="shell">
  <header className="topbar">
   <Logo/>
   <nav className="nav-glass" aria-label="Navigation principale">
    {nav.map(([to,icon,label])=><NavLink key={to} to={to} end={to==='/' }><Icon name={icon}/><span>{label}</span></NavLink>)}
   </nav>
   <Link className="project-pill" to="/contact"><span>J’ai un projet</span><Icon name="arrow" size={15}/></Link>
   <button className="menu-toggle" onClick={()=>setOpen(!open)} aria-expanded={open} aria-label="Ouvrir la navigation">{open?'Fermer':'Menu'}</button>
  </header>
  <AnimatePresence>{open&&<motion.div className="menu-panel" initial={{opacity:0,y:-10}} animate={{opacity:1,y:0}} exit={{opacity:0,y:-10}}>{[...nav,['/contact','contact','J’ai un projet']].map(([to,icon,label])=><NavLink onClick={()=>setOpen(false)} key={to} to={to}><Icon name={icon}/><span>{label}</span><Icon name="arrow" size={15}/></NavLink>)}</motion.div>}</AnimatePresence>
  <main>{children}</main>
  <footer className="footer">
   <div className="footer-main"><Logo/><span>Portfolio de Huriel Nguimbi · Poitiers</span></div>
   <div className="footer-links"><Link to="/projets">Projets</Link><Link to="/expertise">Compétences</Link><Link to="/studio">Vision</Link><Link to="/contact">Contact</Link></div>
   <div className="footer-meta"><a href="mailto:contact@beyond31.online">contact@beyond31.online</a><div><Link to="/mentions-legales">Mentions légales</Link><Link to="/confidentialite">Confidentialité</Link></div></div>
  </footer>
 </div>
}
